    /** The thirteen modules the home board shows, in grid order. */
    val board: List<VaultModule> = VaultModule.entries.filter { it != VaultModule.HOME }

    /**
     * Ids that draw another theme's generated set. The neon trio ships its own palette and board
     * grammar without re-cutting 42 vector plates; each borrows the closest vivid ramp so a tile
     * never falls through to the default brand. The retired ids point at the palette
     * `VaultPalettes.find` hands back, so a stored setting keeps its colours after an upgrade.
     */
    private val aliases = mapOf(
        "neon_cyan" to "voltra",
        "neon_magenta" to "royal",
        "neon_plasma" to "dark",
        "terra" to "sakura",
        "slate" to "dark",
        "carbon" to "noir"
    )

    private fun resolve(themeId: String): String = aliases[themeId] ?: themeId

    fun icon(themeId: String, module: VaultModule): Int =
        icons[resolve(themeId)]?.get(module) ?: icons.getValue(VAULT_DEFAULT).getValue(module)

    fun accent(themeId: String, module: VaultModule): Color =
        argbToColor(accents[resolve(themeId)]?.get(module) ?: accents.getValue(VAULT_DEFAULT).getValue(module))

    /**
     * A brand accent is stored as 0xFFRRGGBB, and `Color(ULong)` is Color's value-class
     * constructor: it takes the already-packed internal representation, so the blue
     * channel lands in the 6-bit color space index and drawing the color throws
     * ArrayIndexOutOfBoundsException on an 18-slot array. Only the Long factory packs
     * ARGB as sRGB, so the conversion has to happen here, once.
     */
    private fun argbToColor(argb: ULong): Color = Color(argb.toLong() and 0xFFFFFFFFL)

    /** The brand's own ramp for the board modules, in grid order. */
    fun ramp(themeId: String): List<Color> =
        VaultModule.entries.filter { it != VaultModule.HOME }.map { accent(themeId, it) }

    private const val VAULT_DEFAULT = "aqua"
}
